import org.evosuite.runtime.EvoRunnerParameters;
import org.evosuite.runtime.ViolatedAssumptionAnswer;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class JsonTypeInfo_ESTest_test02 extends JsonTypeInfo_ESTest_scaffolding {

    @Test(timeout = 4000)
    public void test02() throws Throwable {
        final JsonTypeInfo.Value emptyTypeInfo = JsonTypeInfo.Value.EMPTY;
        final JsonTypeInfo.Value typeInfoWithPropertyName = emptyTypeInfo.withPropertyName("com.fasterxml.jackson.annotation.JsonTypeInfo$Id");
        final boolean emptyEqualsPropertyNamedValue = emptyTypeInfo.equals(typeInfoWithPropertyName);

        assertFalse(typeInfoWithPropertyName.equals((Object) emptyTypeInfo));
        assertFalse(emptyEqualsPropertyNamedValue);
        assertFalse(typeInfoWithPropertyName.getIdVisible());
    }
}
